import{_t as e,it as t,n,rt as r}from"./chunks/framework.CzJE1L4g.js";var i=JSON.parse(`{"title":"更新日志","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":1792657967000}`),a={name:`changelog.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to “更新日志”">​</a></h1><p>本页记录 <code>@xihan-print/core</code>、<code>@xihan-print/runtime</code>、<code>@xihan-print/designer</code> 各版本使用者能感知的变更，每条标注 <strong>新增 / 修复 / 调整 / 移除</strong>。这几个包总是同一个版本号一起发布；逐包的完整记录见仓库里各包的 <code>CHANGELOG.md</code>。打印客户端与它们同号，它的改动写在同一版里，条目开头标明「打印客户端」。</p><h2 id="v1-0-0-rc-2-2026-10-22" tabindex="-1">v1.0.0-rc.2（2026-10-22） <a class="header-anchor" href="#v1-0-0-rc-2-2026-10-22" aria-label="Permalink to “v1.0.0-rc.2（2026-10-22）”">​</a></h2><p>本版设计器的菜单栏可以显示关闭钮，并修正了选中工具条按不动、拖动后留下悬停框两处问题；拖动、拉伸与平移更流畅。所依赖的 XiHan.UI 升到 5.1.0。</p><div class="warning custom-block"><p class="custom-block-title">升级须知</p><ul><li><code>@xihan-ui/*</code> 的 peer 依赖范围改为 <code>^5.1.0</code>：宿主要把 XiHan.UI 一起升到 5.1.0 及以上。</li></ul></div><ul><li><strong>新增</strong> <code>&lt;xh-print-designer&gt;</code> 的 <code>closable</code>：开着时菜单栏最右端多一颗关闭钮，按下派发 <code>close</code>，由宿主关掉编辑器或回到列表，见<a href="./guide/host#关闭编辑器">与宿主集成</a>。</li><li><strong>修复</strong> 选中工具条上的钮（字号、文字样式、对齐与分布、层级、副本、复制、删除）用指针按下时不再清掉选中，命令照常执行。</li><li><strong>修复</strong> 拖动元素松手后，不再在元素原来的位置留下一个悬停框；悬停框跟着元素的当前位置画。</li><li><strong>调整</strong> 拖动、拉伸、旋转元素与平移画布时，途中只重画纸面与覆盖层，属性面板、问题列表、工具栏与菜单栏在松手后更新。</li></ul><h2 id="v1-0-0-rc-1-2026-10-21" tabindex="-1">v1.0.0-rc.1（2026-10-21） <a class="header-anchor" href="#v1-0-0-rc-1-2026-10-21" aria-label="Permalink to “v1.0.0-rc.1（2026-10-21）”">​</a></h2><p>首次发布，以原生 Web Components 交付，不绑定前端框架。模板是纯 JSON，按数据分页预览、在浏览器里打印，也可以经本地打印客户端静默打印。</p><ul><li><strong>新增</strong> <code>@xihan-print/core</code>：打印模板的结构（文档、页面模板、页眉页脚及其变体、元素、表格）、单位换算与页面几何、元素类型登记表、模板校验与问题码、编辑操作与撤销重做、按数据分页排版。纯 TypeScript，不依赖 DOM。</li><li><strong>新增</strong> <code>@xihan-print/runtime</code>：<code>&lt;xh-print-preview&gt;</code> 按模板与数据分页预览，调起浏览器打印；<code>printDocument</code>、<code>paginateDocument</code> 不经预览直接排版、打印，分页的每一步与打印的各个环节可经 <code>trace</code> 回调报告；与 XiHan.UI 内建语言一一对应的界面语言包（<code>@xihan-print/runtime/locale</code>）；本地打印客户端的 SDK（<code>@xihan-print/runtime/client</code>），连不上客户端时退回浏览器打印。</li><li><strong>新增</strong> <code>@xihan-print/designer</code>：<code>&lt;xh-print-designer&gt;</code> 可视化设计器，包括菜单栏、物料与按 <code>fields</code> 列出的字段物料，画布上的选择、移动、缩放、对齐吸附与参考线，表格编辑，属性面板，问题列表，页面设置，设置对话框，新手引导，以及按 <code>draftKey</code> 在本机自动保存的草稿。元素种类、编辑方式、校验规则、属性编辑器、命令、面板、设置分区、导入器、物料来源与菜单栏的菜单都能经 <code>extensions</code> 登记。</li></ul>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};